  'table-row6-col1' => 'विस्तृत विश्लेषण के लिए सर्वोत्तम',
  'table-row6-col2' => 'हाँ',
  'table-row6-col3' => 'हाँ',
  'table-row6-col4' => 'बुनियादी सारांश',
  'table-row6-col5' => 'व्यावसायिक उपयोग',
  'use-cases-heading' => 'एआई पीडीएफ सारांश के मामलों का उपयोग करें',
  'use-cases-intro' => 'पीडीएफ सारांश पेशेवर या शैक्षणिक क्षेत्र में सभी के लिए सहायक होते हैं।',
  'usecase1-heading' => 'छात्र',
  'usecase1-para' => 'छात्र अपनी पढ़ाई के दौरान कई पाठ्यपुस्तकों और शोध पत्रों का प्रबंधन करते हैं। सारांशित पीडीएफ़ उन्हें महत्वपूर्ण विचारों पर शीघ्रता से ध्यान केंद्रित करने में मदद करते हैं। इससे पढ़ने के घंटों की बचत होती है और परीक्षा की तैयारी और मुख्य विषयों की समझ में सुधार होता है। सारांश छात्रों को कुशलतापूर्वक दोहराने और अनावश्यक विवरण के बिना ज्ञान बनाए रखने की अनुमति देता है।',
  'usecase2-heading' => 'शोधकर्ता',
  'usecase2-para' => 'शोधकर्ता प्रतिदिन बड़ी मात्रा में शैक्षणिक पेपर और तकनीकी रिपोर्ट संभालते हैं। सारांशित पीडीएफ प्रासंगिक निष्कर्षों की पहचान करने और सूचना अधिभार से बचने में मदद करते हैं। वे अध्ययनों की तेज़ तुलना और प्रमुख अंतर्दृष्टि के त्वरित निष्कर्षण की अनुमति देते हैं। शोधकर्ता संक्षिप्त सारांशों का उपयोग करके अधिक कुशलता से निर्णय ले सकते हैं और प्रयोगों की योजना बना सकते हैं।',
  'usecase3-heading' => 'पेशेवरों',
  'usecase3-para' => 'पेशेवर कार्यालय सेटिंग में अक्सर रिपोर्ट, नीतियों और परियोजना दस्तावेजों की समीक्षा करते हैं। सारांशित पीडीएफ उन्हें आवश्यक जानकारी तक शीघ्रता से पहुंचने और तेजी से कार्य करने में मदद करते हैं। वे बेहतर उत्पादकता का समर्थन करते हैं और लंबे दस्तावेज़ों पर बर्बाद होने वाले समय को कम करते हैं। स्पष्ट और संक्षिप्त सारांशों का उपयोग करके टीमें अधिक प्रभावी ढंग से सहयोग कर सकती हैं।',
  'conclusion-heading' => 'निष्कर्ष',
  'conclusion-para1-1' => 'पीडीएफ सारांश',
  'conclusion-para1' => 'उपयोगकर्ताओं को लंबे दस्तावेज़ों में मुख्य विचारों को शीघ्रता से समझने में सहायता करें। वे समय बचाते हैं और पढ़ाई और काम में उत्पादकता में सुधार करते हैं। छात्र पाठ्यपुस्तकों और शोध पत्रों के मुख्य बिंदुओं की कुशलतापूर्वक समीक्षा कर सकते हैं।',
  'conclusion-para2' => 'शोधकर्ता कई रिपोर्टों का तेजी से विश्लेषण करते हैं और महत्वपूर्ण निष्कर्षों की प्रभावी ढंग से पहचान करते हैं। पेशेवर संपूर्ण दस्तावेज़ पढ़े बिना रिपोर्टों और नीतियों से महत्वपूर्ण जानकारी तक पहुँच प्राप्त करते हैं। पीडीएफ सारांश एआई सामग्री के आवश्यक अर्थ को संरक्षित करते हुए सटीक सारांश प्रदान करता है। जब सभी के पास संक्षिप्त दस्तावेज़ संस्करण होते हैं तो टीमें अधिक आसानी से सहयोग करती हैं।',
  'conclusion-para3' => 'सारांशित पीडीएफ सूचना अधिभार से तनाव को कम करते हैं और केंद्रित निर्णय लेने की अनुमति देते हैं। कुल मिलाकर, ये उपकरण समझ बढ़ाते हैं और दैनिक कार्यों में महत्वपूर्ण समय बचाते हैं।',
  'faqs-heading' => 'पूछे जाने वाले प्रश्न',
  'faq1-question' => 'क्या एआई पीडीएफ सारांश सटीक है?',
  'faq1-answer' => 'एआई पीडीएफ सारांश अधिकांश मानक दस्तावेजों के लिए सटीक परिणाम प्रदान करता है। सटीकता दस्तावेज़ की जटिलता और स्पष्टता पर निर्भर करती है। स्पष्ट पाठ और संरचित पीडीएफ बेहतर सारांश उत्पन्न करते हैं। यह मुख्य विचारों को प्रभावी ढंग से पकड़ता है लेकिन जटिल लेआउट में छोटे विवरण छूट सकते हैं।',
  'faq2-question' => 'क्या मैं बड़ी पीडीएफ़ का सारांश प्रस्तुत कर सकता हूँ?',
  'faq2-answer' => 'हाँ, अधिकांश AI PDF सारांशकर्ता बड़े दस्तावेज़ों को कुशलतापूर्वक संभालते हैं। कुछ टूल में फ़ाइल आकार सीमाएँ हो सकती हैं या बहुत बड़ी फ़ाइलों को विभाजित करने की आवश्यकता हो सकती है। सारांशीकरण पढ़ने के समय को कम करता है और लंबी रिपोर्ट या पाठ्यपुस्तकों से मुख्य बिंदुओं पर प्रकाश डालता है।',
  'faq3-question' => 'क्या सारांशीकरण मुफ़्त है?',
  'faq3-answer-1' => 'अनेक',
  'faq3-answer-2' => 'एआई पीडीएफ सारांश',
  'faq3-answer-3' => 'मुफ़्त बुनियादी सारांश प्रदान करें। उन्नत सुविधाओं, लंबे सारांशों या बड़े फ़ाइल समर्थन के लिए सशुल्क योजनाओं की आवश्यकता हो सकती है। मुफ़्त संस्करण अभी भी आवश्यक सारांश प्रदान करते हैं, जिससे उपयोगकर्ताओं को समय बचाने और मुख्य जानकारी तक शीघ्रता से पहुंचने में मदद मिलती है।',
  'faq4-question' => 'क्या मैं सारांश निर्यात कर सकता हूँ?',
  'faq4-answer' => 'हाँ, अधिकांश उपकरण पीडीएफ, वर्ड या टेक्स्ट प्रारूप में सारांश निर्यात करने की अनुमति देते हैं। निर्यात करने से उपयोगकर्ता ऑफ़लाइन उपयोग के लिए सारांश सहेज सकते हैं, दूसरों के साथ साझा कर सकते हैं, या अध्ययन नोट्स और पेशेवर रिपोर्ट में कुशलतापूर्वक एकीकृत कर सकते हैं।',
  'faq5-question' => 'क्या अपलोड की गई पीडीएफ़ पीडीएफ समराइज़र पर सुरक्षित हैं?',
  'faq5-answer' => 'प्रतिष्ठित एआई पीडीएफ सारांशकर्ता अपलोड किए गए दस्तावेज़ों की सुरक्षा के लिए एन्क्रिप्शन और सुरक्षित सर्वर का उपयोग करते हैं। वे तीसरे पक्ष के साथ फ़ाइलें साझा नहीं करते हैं. उपयोगकर्ताओं को संवेदनशील या गोपनीय फ़ाइलें अपलोड करने से पहले टूल की गोपनीयता नीति को सत्यापित करना चाहिए।',
);
